(() => {
 const canvas=document.getElementById('preview'),ctx=canvas.getContext('2d');
 const headline=document.getElementById('headline'),support=document.getElementById('support'),palette=document.getElementById('palette'),language=document.getElementById('post-language'),template=document.getElementById('template'),status=document.getElementById('status');
 const sets=[['Make your mark.','Introducing Digits Studio.','yellow'],['More than a logo.','A voice. A look. A reason to remember.','white'],['A website with a job to do.','Help people understand. Then act.','dark'],['Say the right thing. Reach further.','Content and campaigns with a clear purpose.','lilac'],['Two languages. One clear message.','English and Arabic, considered together.','yellow'],['Small studio. Direct connection.','Meet Ahmad Alawieh, founder.','white']];
 const schemes={yellow:['#FFDA46','#292A32'],dark:['#292A32','#FFFFFF'],lilac:['#B4A6ED','#292A32'],white:['#FFFFFF','#292A32']};
 const logos={};let ready=false;
 function loadImage(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=src;});}
 function wrap(text,maxWidth){const paragraphs=text.split('\n'),lines=[];for(const paragraph of paragraphs){let line='';for(const word of paragraph.split(/\s+/)){if(ctx.measureText(word).width>maxWidth){if(line){lines.push(line);line='';}let fragment='';for(const char of word){if(fragment&&ctx.measureText(fragment+char).width>maxWidth){lines.push(fragment);fragment=char;}else fragment+=char;}line=fragment;}else if(line&&ctx.measureText(line+' '+word).width>maxWidth){lines.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)lines.push(line);}return lines;}
 function draw(){if(!ready)return;const [bg,fg]=schemes[palette.value],ar=language.value==='ar';ctx.clearRect(0,0,1080,1350);ctx.fillStyle=bg;ctx.fillRect(0,0,1080,1350);const logo=fg==='#FFFFFF'?logos.white:logos.dark;ctx.drawImage(logo,72,64,295,295*168/557.272);ctx.fillStyle=fg;ctx.direction=ar?'rtl':'ltr';ctx.textAlign=ar?'right':'left';const family=ar?'Arabic':'Archivo';let fontSize=ar?100:118,lines;do{ctx.font=`750 ${fontSize}px ${family}`;lines=wrap(headline.value,936);if(lines.length*fontSize*1.22<=520)break;fontSize-=3;}while(fontSize>47);let y=405;for(const line of lines){ctx.fillText(line,ar?1008:72,y);y+=fontSize*1.22;}ctx.font=`450 30px ${ar?'Arabic':'Instrument'}`;let footLines=wrap(support.value,900);if(footLines.length>2){ctx.font=`450 25px ${ar?'Arabic':'Instrument'}`;footLines=wrap(support.value,900);}footLines.slice(0,3).forEach((line,i)=>ctx.fillText(line,ar?1008:72,1165+i*37));ctx.font=`450 26px ${ar?'Arabic':'Instrument'}`;ctx.fillText(ar?'الهوية. المواقع. التسويق.':'Branding. Websites. Marketing.',ar?1008:72,1280);ctx.font='450 23px Instrument';ctx.direction='ltr';ctx.textAlign='left';ctx.fillText('digitsstudio.online',72,1320);ctx.save();ctx.translate(ar?72:854,972);ctx.scale(1.2,1.2);ctx.fill(new Path2D('M8 8H58C88 8 110 30 110 60S88 112 58 112H8V66H34V86H58C73 86 84 75 84 60S73 34 58 34H8Z'));ctx.restore();status.textContent='';}
 template.addEventListener('change',()=>{const s=sets[Number(template.value)];headline.value=s[0];support.value=s[1];palette.value=s[2];language.value='en';draw();});
 for(const input of [headline,support,palette,language])input.addEventListener('input',draw);
 document.getElementById('download').addEventListener('click',()=>{if(!ready)return;canvas.toBlob(blob=>{if(!blob){status.textContent='Export failed. Try downloading again.';return;}const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='digits-studio-social-post.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='PNG downloaded.';},'image/png');});
 Promise.all([document.fonts.load('750 118px Archivo'),document.fonts.load('450 30px Instrument'),document.fonts.load('750 100px Arabic'),loadImage('brand/logo-primary.svg'),loadImage('brand/logo-white.svg')]).then(results=>{logos.dark=results[3];logos.white=results[4];ready=true;draw();}).catch(()=>{status.textContent='The preview could not load. Open this editor through the local website server and try again.';});
})();
